#!/usr/bin/env python3
from pathlib import Path
import json, re

ROOT=Path(__file__).resolve().parents[1]
BOT=ROOT/'bot.js'
DASH=ROOT/'cloudflare-dashboard'/'dashboard.html'
WORKER=ROOT/'cloudflare-dashboard'/'src'/'worker.js'
VERSION=ROOT/'version.json'
PKG=ROOT/'cloudflare-dashboard'/'package.json'


def one(text, old, new, label):
    c=text.count(old)
    if c!=1:
        raise RuntimeError(f'{label}: expected one occurrence, got {c}')
    return text.replace(old,new,1)


def re_one(text, pattern, repl, label, flags=0):
    out,n=re.subn(pattern,repl,text,count=1,flags=flags)
    if n!=1:
        raise RuntimeError(f'{label}: expected one regex occurrence, got {n}')
    return out

bot=BOT.read_text()
bot=one(bot,'/* Adventure Land • AiO Bot 2.14.10 | 2026-09-10','/* Adventure Land • AiO Bot 2.15.0 | 2026-09-10','bot header')
bot=one(bot,"var VERSION = '2.14.10';","var VERSION = '2.15.0';",'bot version')

# Make the FIRST literal contract complete. This is intentionally required so a running
# 2.14.9 updater (whose parser only sees this literal) can accept the release.
m=re.search(r"var FEATURE_CONTRACT\s*=\s*(\[[\s\S]*?\]);",bot)
if not m: raise RuntimeError('FEATURE_CONTRACT literal missing')
arr=m.group(1)
required=[
 'merchant-bank-warehouse','merchant-active-discovery','merchant-gathering','merchant-discovery-safety',
 'brain-world-model','brain-safe-experiments','brain-goal-planner','brain-explainability','brain-keyword-learning','dashboard-game-sprites'
]
existing=re.findall(r"['\"]([^'\"]+)['\"]",arr)
missing=[x for x in required if x not in existing]
if missing:
    ins=",\n    "+','.join(repr(x) for x in missing)
    arr=arr[:arr.rfind(']')]+ins+"\n  ]"
    bot=bot[:m.start(1)]+arr+bot[m.end(1):]

# Future-proof update contract extraction without eval: collect the literal plus quoted
# FEATURE_CONTRACT.push(...) and concat([...]) additions from downloaded source.
parser_old=re.compile(r"  function v282ExtractContract\(code\)\{[\s\S]*?\n  \}\n  function v282ValidateContract",re.M)
parser_new=r'''  function v282ExtractContract(code){
    var src=String(code||''),m=src.match(/var FEATURE_CONTRACT\s*=\s*(\[[\s\S]*?\]);/);if(!m)return null;
    var out=[],seen={};function addQuoted(s){var q=/['\"]([^'\"]+)['\"]/g,x;while((x=q.exec(String(s||'')))){if(!seen[x[1]]){seen[x[1]]=1;out.push(x[1]);}}}
    addQuoted(m[1]);var p=/FEATURE_CONTRACT\.push\s*\(([\s\S]*?)\)\s*;/g,x;while((x=p.exec(src)))addQuoted(x[1]);
    var c=/FEATURE_CONTRACT\s*=\s*FEATURE_CONTRACT\.concat\s*\((\[[\s\S]*?\])\)\s*;/g;while((x=c.exec(src)))addQuoted(x[1]);
    return out.length?out:null;
  }
  function v282ValidateContract'''
bot,n=parser_old.subn(parser_new,bot,count=1)
if n!=1: raise RuntimeError('v282ExtractContract replacement failed')

# Brain module defaults + keyword learning.
default_anchor="    brainResearchBridgeEnabled: true, brainResearchProfile: 'development', brainResearchHours: 24, brainResearchMaxHighlights: 20, brainResearchAnonymize: true,\n    cloudSyncEnabled: true"
default_new="    brainResearchBridgeEnabled: true, brainResearchProfile: 'development', brainResearchHours: 24, brainResearchMaxHighlights: 20, brainResearchAnonymize: true,\n    brainModuleWorldModel: true, brainModuleDiscovery: true, brainModuleExperiments: true, brainModulePlanner: true, brainModuleEvaluation: true,\n    brainKeywordLearningEnabled: true, brainLearningKeywords: '', brainWorldRecheckHours: 12,\n    cloudSyncEnabled: true"
bot=one(bot,default_anchor,default_new,'brain defaults')
clean_anchor="out.brainResearchAnonymize=out.brainResearchAnonymize!==false; out.cloudSyncEnabled=out.cloudSyncEnabled!==false;"
clean_new="out.brainResearchAnonymize=out.brainResearchAnonymize!==false; out.brainModuleWorldModel=out.brainModuleWorldModel!==false; out.brainModuleDiscovery=out.brainModuleDiscovery!==false; out.brainModuleExperiments=out.brainModuleExperiments!==false; out.brainModulePlanner=out.brainModulePlanner!==false; out.brainModuleEvaluation=out.brainModuleEvaluation!==false; out.brainKeywordLearningEnabled=out.brainKeywordLearningEnabled!==false; out.brainLearningKeywords=safeString(out.brainLearningKeywords||'',600); out.brainWorldRecheckHours=clamp(out.brainWorldRecheckHours,1,168); out.cloudSyncEnabled=out.cloudSyncEnabled!==false;"
bot=one(bot,clean_anchor,clean_new,'brain clean config')

# Rename the launcher. Keep the key 'brain' for compatibility.
bot=one(bot,"['brain','spark',(C.language==='de'?'Gehirn':'Brain'),'Lebendiges Lernsystem · Teacher, Champion & Challenger']","['brain','spark',(C.language==='de'?'Bot-Gehirn':'Bot Brain'),'Weltwissen · Discovery · Experimente · Planner · Selbstprüfung']",'brain launcher')

